package utils;

import net.serenitybdd.model.environment.EnvironmentSpecificConfiguration;
import net.thucydides.model.environment.SystemEnvironmentVariables;
import net.thucydides.model.util.EnvironmentVariables;

public class EnvironmentConfig {

    private static final EnvironmentVariables variables =
            SystemEnvironmentVariables.createEnvironmentVariables();

    public static String getUsername() {
        return EnvironmentSpecificConfiguration.from(variables)
                .getProperty("credentials.username");
    }

    public static String getPassword() {
        return EnvironmentSpecificConfiguration.from(variables)
                .getProperty("credentials.password");
    }

    public static String getBaseUrl() {
        return EnvironmentSpecificConfiguration.from(variables)
                .getProperty("webdriver.base.url");
    }

    private EnvironmentConfig() {
    }
}

package utils;

import com.typesafe.config.Config;
import com.typesafe.config.ConfigFactory;

public class EnvironmentConfig {

    private static final Config DEFAULT_ENV = ConfigFactory
            .load("serenity")
            .getConfig("environments.default");

    public static String getUsername() {
        return DEFAULT_ENV.getString("credentials.username");
    }

    public static String getPassword() {
        return DEFAULT_ENV.getString("credentials.password");
    }

    public static String getBaseUrl() {
        return DEFAULT_ENV.getString("webdriver.base.url");
    }

    private EnvironmentConfig() {
    }
}

plugins {
    id 'java'
    id 'net.serenity-bdd.serenity-gradle-plugin' version '4.2.34'
}

group = 'com.devsu.e2e'
version = '1.0.0'

java {
    sourceCompatibility = JavaVersion.VERSION_17
    targetCompatibility = JavaVersion.VERSION_17
}

repositories {
    mavenCentral()
}

ext {
    serenityVersion = '4.2.34'
    junitVersion = '4.13.2'
    assertjVersion = '3.26.3'
}

dependencies {
    testImplementation "net.serenity-bdd:serenity-core:${serenityVersion}"
    testImplementation "net.serenity-bdd:serenity-junit:${serenityVersion}"
    testImplementation "net.serenity-bdd:serenity-cucumber:${serenityVersion}"
    testImplementation "net.serenity-bdd:serenity-screenplay:${serenityVersion}"
    testImplementation "net.serenity-bdd:serenity-screenplay-webdriver:${serenityVersion}"
    testImplementation "net.serenity-bdd:serenity-ensure:${serenityVersion}"
    testImplementation "org.assertj:assertj-core:${assertjVersion}"
    testImplementation "junit:junit:${junitVersion}"
}

test {
    useJUnit()
    testLogging {
        events 'PASSED', 'FAILED', 'SKIPPED'
    }
    systemProperty 'file.encoding', 'UTF-8'
}

serenity {
    reports = ['single-page-html']
}

